const MM_TO_PX = 3.7795275591; // 96dpi
function writerCssLengthToPt(raw) {
  const value = String(raw || "").trim().toLowerCase().match(/^(-?[\d.]+)\s*(px|pt|cm|mm|in)?$/);
  if (!value) return null;
  const n = Number(value[1]);
  const unit = value[2] || "px";
  return n * (unit === "pt" ? 1 : unit === "cm" ? 72 / 2.54 : unit === "mm" ? 72 / 25.4 : unit === "in" ? 72 : 0.75);
}

function pageSizeMm(setup) {
  if (setup?.size === "custom" && Number.isFinite(setup.widthMm) && Number.isFinite(setup.heightMm)) {
    return { label: `Tùy chỉnh (${setup.widthMm} × ${setup.heightMm} mm)`, w: setup.widthMm, h: setup.heightMm };
  }
  return PAGE_SIZES_MM[setup?.size] || PAGE_SIZES_MM.a4;
}
/** LibreOffice 26.2.5 drops tracked-changes unless office:change-info has a date. Session canvas markers have none. */
const FODT_TRACK_CHANGE_SENTINEL_DATE = "1970-01-01T00:00:00";

/**
 * Chuyển đổi số nguyên dương sang chữ số La Mã (dành cho Endnotes chuẩn Word)
 * @param {number} num
 * @returns {string}
 */
export function toRoman(num) {
  const romanMap = [
    [1000, "m"], [900, "cm"], [500, "d"], [400, "cd"],
    [100, "c"], [90, "xc"], [50, "l"], [40, "xl"],
    [10, "x"], [9, "ix"], [5, "v"], [4, "iv"], [1, "i"]
  ];
  let res = "";
  let n = Math.max(1, parseInt(num, 10) || 1);
  for (const [val, roman] of romanMap) {
    while (n >= val) {
      res += roman;
      n -= val;
    }
  }
  return res || "i";
}

function trapFocus(dialogBox, event) {
  if (event.key !== "Tab") return;
  const focusables = Array.from(dialogBox.querySelectorAll(
    'button:not([disabled]):not([style*="display: none"]):not([style*="display:none"]), ' +
    'input:not([disabled]):not([type="hidden"]):not([style*="display: none"]):not([style*="display:none"]), ' +
    'select:not([disabled]), textarea:not([disabled]), [tabindex]:not([tabindex="-1"])'
  )).filter(el => el.offsetParent !== null || el.offsetWidth > 0 || el.offsetHeight > 0);

  if (focusables.length === 0) return;
  const first = focusables[0];
  const last = focusables[focusables.length - 1];

  if (event.shiftKey) {
    if (document.activeElement === first || !dialogBox.contains(document.activeElement)) {
      event.preventDefault();
      last.focus();
    }
  } else {
    if (document.activeElement === last || !dialogBox.contains(document.activeElement)) {
      event.preventDefault();
      first.focus();
    }
  }
}

const WRITER_MULTILEVEL_PRESETS = {
  decimal: { className: "vno-ml-decimal", styleName: "LMultiDecimal" },
  letter: { className: "vno-ml-letter", styleName: "LMultiLetter" },
  nd30: { className: "vno-ml-nd30", styleName: "LMultiNd30" },
  custom: { className: "vno-ml-custom", styleName: "LMultiCustom" }
};
const WRITER_MULTILEVEL_BY_CLASS = Object.fromEntries(
  Object.values(WRITER_MULTILEVEL_PRESETS).map((preset) => [preset.className, preset.styleName])
);
const WRITER_MULTILEVEL_BY_STYLE = Object.fromEntries(
  Object.values(WRITER_MULTILEVEL_PRESETS).map((preset) => [preset.styleName, preset.className])
);
const WRITER_LIST_STYLE_NAMES = new Set(["LBullet", "LNumber", ...Object.keys(WRITER_MULTILEVEL_BY_STYLE)]);
const WRITER_MULTILEVEL_MAX_DEPTH = 9;

function fodtListLevelNumberXml({ level, format, suffix = ".", prefix = "", displayLevels, spaceBeforeCm }) {
  const attrs = [`text:level="${level}"`, `style:num-format="${format}"`];
  if (prefix) attrs.push(`style:num-prefix="${prefix}"`);
  if (suffix !== "") attrs.push(`style:num-suffix="${suffix}"`);
  if (displayLevels) attrs.push(`text:display-levels="${displayLevels}"`);
  return `<text:list-level-style-number ${attrs.join(" ")}><style:list-level-properties text:space-before="${spaceBeforeCm}cm" text:min-label-width="0.635cm"/></text:list-level-style-number>`;
}

function fodtMultilevelListStyleXml(styleName) {
  const space = [0.635, 1.27, 1.905];
  if (styleName === "LMultiDecimal") {
    return `<text:list-style style:name="LMultiDecimal">${fodtListLevelNumberXml({ level: 1, format: "1", suffix: ".", spaceBeforeCm: space[0] })}${fodtListLevelNumberXml({ level: 2, format: "1", suffix: ".", displayLevels: 2, spaceBeforeCm: space[1] })}${fodtListLevelNumberXml({ level: 3, format: "1", suffix: ".", displayLevels: 3, spaceBeforeCm: space[2] })}</text:list-style>`;
  }
  if (styleName === "LMultiLetter") {
    return `<text:list-style style:name="LMultiLetter">${fodtListLevelNumberXml({ level: 1, format: "1", suffix: ".", spaceBeforeCm: space[0] })}${fodtListLevelNumberXml({ level: 2, format: "a", suffix: ".", spaceBeforeCm: space[1] })}${fodtListLevelNumberXml({ level: 3, format: "i", suffix: ".", spaceBeforeCm: space[2] })}</text:list-style>`;
  }
  if (styleName === "LMultiNd30") {
    return `<text:list-style style:name="LMultiNd30">${fodtListLevelNumberXml({ level: 1, format: "1", prefix: "Điều ", suffix: ".", spaceBeforeCm: space[0] })}${fodtListLevelNumberXml({ level: 2, format: "1", suffix: ".", spaceBeforeCm: space[1] })}${fodtListLevelNumberXml({ level: 3, format: "a", suffix: ")", spaceBeforeCm: space[2] })}</text:list-style>`;
  }
  return "";
}

function fodtCustomMultilevelListStyleXml(levels, escapeXml) {
  const styles = (levels || []).slice(0, 9).map((level, index) => {
    const levelNumber = index + 1;
    const fmt = ({ decimal: "1", lowerLetter: "a", upperLetter: "A", lowerRoman: "i", upperRoman: "I", bullet: "bullet" })[level.format] || "1";
    const before = escapeXml(level.prefix || "");
    const after = escapeXml(level.suffixType === "nothing" ? "" : level.suffixType === "space" ? `${level.suffix || ""} ` : level.suffix || "");
    const numberCm = Math.max(0, Number(level.numberCm) || 0);
    const textCm = Math.max(numberCm, Number(level.textCm) || 0.635 * levelNumber);
    const props = `<style:list-level-properties text:space-before="${textCm}cm" text:min-label-width="${Math.max(0.05, textCm - numberCm)}cm"/>`;
    if (fmt === "bullet") return `<text:list-level-style-bullet text:level="${levelNumber}" text:bullet-char="${before || "•"}">${props}</text:list-level-style-bullet>`;
    const display = level.includeParents && levelNumber > 1 ? ` text:display-levels="${levelNumber}"` : "";
    const start = Math.min(32767, Math.max(1, Number(level.start) || 1));
    return `<text:list-level-style-number text:level="${levelNumber}" text:start-value="${start}" style:num-format="${fmt}" style:num-prefix="${before}" style:num-suffix="${after}"${display}><style:list-level-properties text:space-before="${textCm}cm" text:min-label-width="${Math.max(0.05, textCm - numberCm)}cm"/></text:list-level-style-number>`;
  }).join("");
  return `<text:list-style style:name="LMultiCustom">${styles}</text:list-style>`;
}

function multilevelStyleFromClass(className) {
  const tokens = String(className || "").split(/\s+/);
  for (const token of tokens) {
    if (WRITER_MULTILEVEL_BY_CLASS[token]) return WRITER_MULTILEVEL_BY_CLASS[token];
  }
  return "";
}

/** Replace literal text in existing text nodes while preserving their DOM wrappers. */
export function replaceTextInTextNodes(nodes, findText, replacementText, replaceAll = false, options = {}) {
  const needle = String(findText ?? "");
  if (!needle) return 0;
  const replacement = String(replacementText ?? "");
  let replacements = 0;
  const matcher = createMatcher(needle, options);
  for (const node of nodes || []) {
    if (!node || typeof node.data !== "string") continue;
    if (options.format && !nodeMatchesFormat(node, options.format)) continue;
    const res = matcher.replace(node.data, replacement, replaceAll);
    if (res.count > 0) {
      node.data = res.text;
      replacements += res.count;
      if (!replaceAll) break;
    }
  }
  return replacements;
}

export function resolveWriterTabBehavior({
  inTable = false,
  cellIndex = -1,
  cellCount = 0,
  inListAtStart = false,
  shiftKey = false
} = {}) {
  if (inTable) {
    if (shiftKey) return cellIndex > 0 ? "previousCell" : "ignore";
    return cellIndex >= 0 && cellIndex === cellCount - 1 ? "appendTableRow" : "nextCell";
  }
  if (inListAtStart) return shiftKey ? "listOutdent" : "listIndent";
  return shiftKey ? "ignore" : "insertTab";
}

/**
 * Apply [start, end, value] replacements given in DESCENDING start order. Disjoint ones are joined once from
 * left to right; the previous per-replacement slice/concat re-copied the whole document each time
 * (O(replacements x length)). Overlapping replacements, or globalThis.__VNO_OPEN_LEGACY, keep that original splice.
 */
function applyDescendingReplacements(text, replacements) {
  let disjoint = globalThis.__VNO_OPEN_LEGACY !== true;
  for (let r = 1; disjoint && r < replacements.length; r++) {
    if (replacements[r - 1][0] < replacements[r][1]) disjoint = false; // previous (later) one starts before this one ends
  }
  if (!disjoint) {
    let out = text;
    for (const [start, end, value] of replacements) out = out.slice(0, start) + value + out.slice(end);
    return out;
  }
  const pieces = [];
  let at = 0;
  for (let r = replacements.length - 1; r >= 0; r--) {
    const [start, end, value] = replacements[r];
    pieces.push(text.slice(at, start), value);
    at = end;
  }
  pieces.push(text.slice(at));
  return pieces.join("");
}

