        if (!Number.isFinite(pos) || pos <= 0) return null;
        const align = alignments[attrs.match(/\bw:val=["']([^"']+)["']/i)?.[1]?.toLowerCase()] || "l";
        const leader = leaders[attrs.match(/\bw:leader=["']([^"']+)["']/i)?.[1]?.toLowerCase()] || "n";
