        if (!/<w:t\b[^>]*>[^<]*\S/.test(rm[1])) continue;
        const rpr = rm[1].match(/<w:rPr>([\s\S]*?)<\/w:rPr>/)?.[1] || "";
        const own = rpr.match(/<w:w\b[^>]*w:val="(\d+)"/)?.[1];
        const rStyle = rpr.match(/<w:rStyle\b[^>]*w:val="([^"]+)"/)?.[1];
